import json

def make_output_grid():
    """Create output by filling diamond's hollow center with 2, 3 from rectangle pattern"""
    output = [[0 for _ in range(15)] for _ in range(18)]

    # Input - holes of 1s
    # Row 6: cols 5,6 = 1,1
    # Row 7: cols 4,7 = 1,1 (cols 5,6 are hollow to fill)
    # Row 8: cols 3-8 = 1,1,1,1,1,1
    # Rectangle: rows 14-16, cols 8-12 with [2,3,1,8,7]

    for i in range(18):
        for j in range(15):
            if i == 6:
                if j in [5, 6]:
                    output[i][j] = 1
            elif i == 7:
                if j in [4, 7]:
                    output[i][j] = 1
            elif i == 8:
                if j in [3, 4, 5, 6, 7, 8]:
                    output[i][j] = 1
            elif 14 <= i <= 16:
                if 8 <= j <= 12:
                    pattern = [2, 3, 1, 8, 7]
                    col_in_pattern = (j - 8) % 5
                    output[i][j] = pattern[col_in_pattern]
            else:
                # Hollow fill positions in diamond: row 7, cols 5-6 = 2, 3
                if i == 7 and j in [5, 6]:
                    col_in_pattern = (j - 8) % 5  # For j=5: 2, j=6: 3
                    output[i][j] = [2, 3, 1, 8, 7][col_in_pattern]
                else:
                    output[i][j] = 0

    return output

